#Requires -Version 7.0
[CmdletBinding()]
param([Parameter(Mandatory)][string]$InstallerReceipt)
$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest
$hostPath = 'C:\Program Files\PowerShell\7\pwsh.exe'
if (-not [Environment]::Is64BitProcess -or (Get-Process -Id $PID).Path -ine $hostPath) { throw 'HOLD_UNAPPROVED_HOST' }
$env:PSModulePath = Join-Path $PSHOME 'Modules'
Import-Module (Join-Path $PSHOME 'Modules\Microsoft.PowerShell.Security\Microsoft.PowerShell.Security.psd1')
$hostSig = Get-AuthenticodeSignature -LiteralPath $hostPath
if ($hostSig.Status -ne 'Valid' -or
    $hostSig.SignerCertificate.Subject -notmatch '(^|,\s*)O=Microsoft Corporation(,|$)') { throw 'HOLD_HOST_SIGNATURE' }

$id = [Security.Principal.WindowsIdentity]::GetCurrent()
try {
    $expectedSid = ([Security.Principal.NTAccount]::new([Environment]::MachineName,'windows')).Translate([Security.Principal.SecurityIdentifier])
    if (-not $expectedSid.Equals($id.User) -or
        -not ([Security.Principal.WindowsPrincipal]::new($id)).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
        throw 'HOLD_DEPLOY_TOKEN'
    }
    $sid = $id.User.Value
} finally { $id.Dispose() }

$expectedSha = '52694e574cee3068e0c84131dcd9b93d19a2b59a42a63cf322c87a596c91806d'
$thumb = '437423567AD4B703578F231E34A06592B38DB4EB'
$derSha = '7dba5310d6ded0035595e5e7ab8b8b73422f2925b49c633426995c322940672c'
$spkiSha = '2a6d0a7d31e7642df209b6cbe12fa628500663f540eb6bd557cac2aca2d31f7c'
$name = 'Limitless.InitialStagingInstaller.exe'

function Assert-SignedImage([string]$path) {
    $signature = Get-AuthenticodeSignature -LiteralPath $path
    $leaf = $signature.SignerCertificate
    if ($signature.Status -ne 'Valid' -or $null -eq $leaf -or $leaf.Thumbprint -cne $thumb) {
        throw 'HOLD_VERIFIER_AUTHENTICODE'
    }
    $rsa = [Security.Cryptography.X509Certificates.RSACertificateExtensions]::GetRSAPublicKey($leaf)
    try {
        $eku = @($leaf.Extensions |
            Where-Object { $_ -is [Security.Cryptography.X509Certificates.X509EnhancedKeyUsageExtension] } |
            ForEach-Object EnhancedKeyUsages | ForEach-Object Value)
        $now = Get-Date
        if ($null -eq $rsa -or
            $leaf.GetCertHashString([Security.Cryptography.HashAlgorithmName]::SHA256).ToLowerInvariant() -cne $derSha -or
            [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($rsa.ExportSubjectPublicKeyInfo())).ToLowerInvariant() -cne $spkiSha -or
            $eku -notcontains '1.3.6.1.5.5.7.3.3' -or $now -lt $leaf.NotBefore -or $now -ge $leaf.NotAfter) {
            throw 'HOLD_VERIFIER_SIGNER'
        }
    } finally { if ($null -ne $rsa) { $rsa.Dispose() } }
    return $leaf
}
$embeddedAssembly = ''
if ($InstallerReceipt -cnotmatch '^[a-f0-9]{16}:[a-f0-9]{32}:[a-f0-9]{64}$') { throw 'HOLD_INSTALLER_RECEIPT_FORMAT' }
$sourceName = 'StagingSource.ps1'
$sigName = 'StagingSource.sig'
$expectedSource = 'caf59966f74e5d5d520a6a5245e9c118c75320ff138efe757d36619a058a37f7'
$expectedDetached = '6892ef8aa4b5e85c20d5bd94e25e48e96d25dc116860ff2f0c9070bb74b0d388'
function Read-BoundBytes([IO.Stream]$stream, [int]$limit, [string]$expected) {
    $stream.Position = 0
    if ($stream.Length -lt 1 -or $stream.Length -gt $limit) { throw 'HOLD_BINDING_INPUT_SIZE' }
    $data = [byte[]]::new([int]$stream.Length)
    $stream.ReadExactly($data)
    if ([Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($data)).ToLowerInvariant() -cne $expected) {
        throw 'HOLD_BINDING_INPUT_SHA'
    }
    return ,$data
}
function Assert-DetachedPss($leaf, [byte[]]$bytes, [byte[]]$signature) {
    $key = [Security.Cryptography.X509Certificates.RSACertificateExtensions]::GetRSAPublicKey($leaf)
    if ($null -eq $key) { throw 'HOLD_PSS_PUBLIC_KEY' }
    try {
        if (-not $key.VerifyData($bytes, $signature, [Security.Cryptography.HashAlgorithmName]::SHA256,
            [Security.Cryptography.RSASignaturePadding]::Pss)) { throw 'HOLD_PSS_READBACK' }
    } finally { $key.Dispose() }
}

$type = [Reflection.Assembly]::Load([Convert]::FromBase64String($embeddedAssembly)).GetType('LimitlessVerifierStorePreparation', $true)
try {
    $transferType = $type.GetNestedType('StagingInputTransfer')
    $start = [DateTimeOffset]::UtcNow
    $transfer = [Activator]::CreateInstance($transferType, [object[]]@($sid,$start,$start.AddMinutes(5)))
    try {
        $installer = $transfer.OpenInstaller()
        try {
            if ($transfer.ReadReceipt($installer,$name,$true) -cne $InstallerReceipt -or
                [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($installer)).ToLowerInvariant() -cne $expectedSha) {
                throw 'HOLD_INSTALLER_RUNTIME_BINDING'
            }
            $transfer.DemandInputsAbsent()
            $origin = $transfer.OpenInput($sourceName,$false)
            try {
                $originSig = $transfer.OpenInput($sigName,$false)
                try {
                    $sourceBytes = Read-BoundBytes $origin 1048576 $expectedSource
                    $sigBytes = Read-BoundBytes $originSig 4096 $expectedDetached
                    $srcFolder = $transferType.GetField('SourceFolder').GetRawConstantValue()
                    $dstFolder = $transferType.GetField('RuntimeFolder').GetRawConstantValue()
                    $sourceLeaf = Assert-SignedImage (Join-Path $srcFolder $sourceName)
                    Assert-DetachedPss $sourceLeaf $sourceBytes $sigBytes

                    $transfer.DemandInputsAbsent()
                    $writtenSource = $transfer.CopyInputNew($sourceName,$sourceBytes)
                    $writtenSig = $transfer.CopyInputNew($sigName,$sigBytes)
                    $copy = $transfer.OpenInput($sourceName,$true)
                    try {
                        $copySig = $transfer.OpenInput($sigName,$true)
                        try {
                            $copyBytes = Read-BoundBytes $copy 1048576 $expectedSource
                            $copySignatureBytes = Read-BoundBytes $copySig 4096 $expectedDetached
                            $copyLeaf = Assert-SignedImage (Join-Path $dstFolder $sourceName)
                            Assert-DetachedPss $copyLeaf $copyBytes $copySignatureBytes
                            if ($transfer.ReadReceipt($copy,$sourceName,$true) -cne $writtenSource -or
                                $transfer.ReadReceipt($copySig,$sigName,$true) -cne $writtenSig -or
                                $transfer.ReadReceipt($installer,$name,$true) -cne $InstallerReceipt) {
                                throw 'HOLD_STAGING_INPUT_ID_CHANGED'
                            }
                            'STAGING_INPUTS_DEPLOYED_HANDLE_VERIFIED'
                            "DEPLOYED_STAGING_SOURCE_SHA256=$expectedSource"
                            "DEPLOYED_STAGING_SIGNATURE_SHA256=$expectedDetached"
                        } finally { $copySig.Dispose() }
                    } finally { $copy.Dispose() }
                } finally { $originSig.Dispose() }
            } finally { $origin.Dispose() }
        } finally { $installer.Dispose() }
    } finally { $transfer.Dispose() }
} catch {
    $cause = $_.Exception.GetBaseException()
    if ($cause -is [ComponentModel.Win32Exception]) { throw ("HOLD_STAGE_INPUT_NATIVE_NO_RETRY_{0}" -f $cause.NativeErrorCode) }
    if ($cause.Message -match '^HOLD_[A-Z_]+$') { throw $cause.Message }
    throw 'HOLD_STAGE_INPUT_NO_RETRY'
}
